.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  cursor: pointer;
  transition: transform var(--motion-base), box-shadow var(--motion-base),
    background var(--motion-base), border-color var(--motion-base), color var(--motion-base);
}

/* ── 主要行動：光的漸層藥丸 ── */
.primary {
  padding: 14px 34px;
  border: none;
  border-radius: var(--radius-pill);
  background: var(--gradient-brand);
  color: var(--color-accent-ink);
  font-size: var(--fs-body-lg);
  font-weight: 500;
  letter-spacing: var(--tracking-button);
  box-shadow: 0 8px 30px rgba(187, 147, 122, 0.28);
}

.primary:hover:not(.disabled) {
  transform: translateY(-2px);
  box-shadow: 0 12px 44px rgba(187, 147, 122, 0.42);
}

/* ── 次要行動：霧面藥丸 ── */
.secondary {
  padding: 13px 28px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-pill);
  background: var(--surface-3);
  color: var(--color-fg-body);
  font-size: var(--fs-body);
  letter-spacing: 0.04em;
  backdrop-filter: blur(8px);
}

.secondary:hover:not(.disabled) {
  background: var(--surface-hover-strong);
}

/* ── 儀式感的外框藥丸（入口儀式「我準備好了」） ── */
.outline {
  padding: 13px 34px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: var(--radius-pill);
  background: var(--surface-3);
  color: rgba(255, 255, 255, 0.9);
  font-size: var(--fs-body);
  letter-spacing: 0.08em;
  backdrop-filter: blur(8px);
}

.outline:hover:not(.disabled) {
  background: var(--surface-hover-strong);
  border-color: rgba(255, 255, 255, 0.55);
}

/* ── 純文字 ── */
.text {
  padding: 0;
  border: none;
  background: none;
  color: var(--color-fg-subtle);
  font-size: var(--fs-body-sm);
  letter-spacing: 0.04em;
}

.text:hover:not(.disabled) {
  color: rgba(255, 255, 255, 0.9);
}

/* ── 帶底線的文字連結 ── */
.link {
  padding: 0;
  border: none;
  background: none;
  color: var(--color-fg-subtle);
  font-size: var(--fs-body-sm);
  letter-spacing: 0.05em;
  text-decoration: underline;
  text-underline-offset: 5px;
  text-decoration-color: rgba(255, 255, 255, 0.2);
}

.link:hover:not(.disabled) {
  color: rgba(255, 255, 255, 0.9);
}

/* ── 極淡的輔助切換（Demo 狀態預覽） ── */
.quiet {
  padding: 0;
  border: none;
  background: none;
  color: var(--color-fg-ghost);
  font-size: 12px;
  letter-spacing: 0.05em;
}

.quiet:hover:not(.disabled) {
  color: var(--color-fg-muted);
}

/* ── 破壞性確認 ── */
.danger {
  padding: 11px 24px;
  border: none;
  border-radius: var(--radius-pill);
  background: var(--color-danger);
  color: #fff;
  font-size: var(--fs-body);
  font-weight: 500;
}

.danger:hover:not(.disabled) {
  transform: translateY(-2px);
}

.compact {
  padding: 12px 28px;
  font-size: var(--fs-body);
}

.disabled {
  cursor: not-allowed;
}

/* ── loading 狀態：旋轉光束外框 ── */
.beam {
  position: relative;
  display: inline-flex;
  flex: none;
  align-self: center;
  padding: 2px;
  overflow: hidden;
  border-radius: 14px;
}

.beam::before {
  content: '';
  position: absolute;
  inset: -50%;
  background: conic-gradient(from 0deg, transparent 0 72%, #ff8a00 84%, #ede9e0 90%, transparent 96%);
  animation: spin 3s linear infinite;
}

.beamInner {
  position: relative;
  border-radius: 12px;
  background: #232326;
}

@keyframes spin {
  to {
    transform: rotate(1turn);
  }
}

.primary.disabled {
  background: var(--surface-hover-strong);
  color: var(--color-fg-hushed);
  box-shadow: none;
}

.secondary.disabled,
.outline.disabled,
.text.disabled,
.link.disabled,
.quiet.disabled,
.danger.disabled {
  opacity: 0.45;
}
